-- ============================================================================
-- ADVERTENCIA (agregada por Atlas, 2026-07-29). NO EJECUTAR CONTRA LA BASE DE ATLAS.
-- ============================================================================
-- Este script proviene de atlas-gil (fork antiguo de Atlas) y actualiza el contenido
-- de encuesta de ESE repositorio. Se conserva aqui solo como referencia de entrega.
--
-- RIESGO VERIFICADO (2026-07-29): atlas-gil comparte el linaje de la semilla con
-- cnv-atlas, asi que este script SI PODRIA EJECUTARSE CON EXITO contra la base de
-- Atlas, en silencio y sin error:
--   - apunta a survey_version_id '55555555-5555-5555-5555-555555555552', el MISMO id
--     que usa nuestro seed (supabase/seed.ts:80);
--   - sus ids de pregunta son sha1 de la clave, con la MISMA derivacion que el seed
--     (seed.ts:85, "atlas-survey-v1:"+clave), asi que COINCIDEN por construccion.
-- Correrlo contra Atlas actualizaria el texto de 63 preguntas, insertaria una nueva y
-- reordenaria todo. Un script que FALLA es seguro; este FUNCIONA donde no debe.
--
-- NO se corre contra Atlas. La siembra de Atlas se hace SOLO por supabase/seed.ts.
-- El patron seguro de siembra no destructiva (que este script ilustra bien) esta en
-- BACKLOG.md, en el gate de siembra del Hito 2.
-- ============================================================================
--
-- Atlas / atlas-gil: sincroniza el contenido de la encuesta (D1-D8) con supabase/seed.ts
-- Generado desde supabase/seed.ts. NO borra survey_answers ni survey_responses.
-- Solo inserta preguntas/opciones nuevas y actualiza texto y orden de las existentes.
-- Los ids son deterministas (sha1 de la clave), por eso el upsert es idempotente.
-- Preguntas: 63. Opciones: 293.

BEGIN;

-- 1) Aparca el orden en un rango alto. La restriccion unica (survey_version_id,
--    order_index) se valida fila a fila, asi que reordenar en sitio puede chocar.
UPDATE survey_questions SET order_index = order_index + 1000
 WHERE survey_version_id = '55555555-5555-5555-5555-555555555552' AND order_index < 1000;

-- 2) Preguntas (inserta las nuevas, actualiza las que ya estan).
ON CONFLICT (id) DO UPDATE SET
  question_text = EXCLUDED.question_text,
  question_type = EXCLUDED.question_type,
  field_key = EXCLUDED.field_key,
  section = EXCLUDED.section,
  order_index = EXCLUDED.order_index,
  data_class = EXCLUDED.data_class,
  used_in_diagnosis = EXCLUDED.used_in_diagnosis;

-- 3) Opciones (value queda NULL: el motor lee option_text, no un puntaje).
ON CONFLICT (id) DO UPDATE SET
  option_text = EXCLUDED.option_text,
  value = EXCLUDED.value,
  order_index = EXCLUDED.order_index;

COMMIT;

-- 4) Control (fuera de la transaccion, solo lee). Esperado:
--    total = 63, huerfanas = 0, respuestas = las que ya hubiera (no se tocan).
--    Si huerfanas > 0, la BD tiene preguntas que ya no estan en el seed: quedaron
--    aparcadas en order_index 1000+ y saldrian al final. No las borres, avisale a Gil.
SELECT
  count(*) FILTER (WHERE order_index < 1000) AS total,
  count(*) FILTER (WHERE order_index >= 1000) AS huerfanas
  FROM survey_questions
 WHERE survey_version_id = '55555555-5555-5555-5555-555555555552';
